INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('hijrah-to-madinah','hijrah-to-madinah','The Hijrah: Migration to Madinah','الهجرة إلى المدينة','A sourced introduction to the Prophet’s migration','seerah','historical','The Hijrah was the migration of the Prophet Muhammad ﷺ from Makkah to Madinah. Qur’an 9:40 recalls the cave episode; a detailed report in Sahih al-Bukhari 3905 describes the preparation, the company of Abu Bakr, the stay in the cave, and the journey onward. This is a verified-reference introductory account; a complete historical chronology requires further scholarly editorial review.','Introductory source-led Seerah reference; full scholarly authentication of narrative pending.','hijrah,hijra,hijrat,prophet migration,migration to madinah,migration to medina,journey to madinah,cave of thawr,cave of thaur,emigration to madinah','Editorial draft based on cited primary references; qualified Seerah specialist review required.','editorial_draft','published','60');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('hijrah-to-madinah-s1','hijrah-to-madinah','What the Hijrah refers to','historical','The Hijrah refers to the migration from Makkah to Madinah associated with the Prophet Muhammad ﷺ and the earliest Muslim community. It was not merely a change of location: the move came in a period when Muslims faced opposition in Makkah and found a new community setting in Madinah. The detailed chain of events should be reconstructed from authenticated reports rather than unsourced popular stories.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('hijrah-to-madinah-s2','hijrah-to-madinah','The cave and divine reassurance','scripture','Surah At-Tawbah 9:40 refers to the Prophet as one of two people in a cave when he reassured his companion not to grieve. This Qur’anic passage is a primary reference for the cave episode. The verse should be read in its full Qur’anic context; the verse alone does not supply every historical detail of the migration.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('hijrah-to-madinah-s3','hijrah-to-madinah','What the detailed report records','transmission','Sahih al-Bukhari 3905 contains a report from Aishah about migration preparations, Abu Bakr waiting to accompany the Prophet, and their time in a cave at Mount Thawr. The report also names helpers, describes provisions and guidance arrangements, and narrates the continuation of the journey. These details are attributed to that report and should not be generalized into a fully dated travel itinerary without additional evidence.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('hijrah-to-madinah-s4','hijrah-to-madinah','What remains to research','methodology','The exact chronology, wider community migration, reception in Madinah, and development of the new community require a fuller comparison of Qur’anic verses, authenticated Hadith and critically assessed Seerah literature. This introductory dossier does not claim to establish every reported incident or a definitive historical date. Editorial review by a qualified Seerah specialist is pending.','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('hijrah-to-madinah-r1','hijrah-to-madinah','quran','The Qur’an — At-Tawbah','9:40','https://quran.com/9/40','The cave episode and reassurance','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('hijrah-to-madinah-r2','hijrah-to-madinah','hadith','Sahih al-Bukhari — Merits of the Ansar','3905','https://sunnah.com/bukhari:3905','Migration details reported by Aishah','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('hijrah-to-madinah-r3','hijrah-to-madinah','hadith','Sahih al-Bukhari — Merits of the Ansar','3905 (chapter: Emigration to Madinah)','https://sunnah.com/bukhari/63/130','Chapter and source context','pending','3');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('battle-of-badr-sourced-account','battle-of-badr-sourced-account','The Battle of Badr: What Primary Sources Establish','غزوة بدر','Qur’anic account and historical reports','seerah','historical','The Battle of Badr is mentioned by name in Qur’an 3:123, which recalls help granted to the early Muslims. Qur’an 8:42 describes the relative positions of the parties and the caravan. Sahih al-Bukhari 3951 records a report from Ka‘b ibn Malik about how the expedition developed. These sources establish a reliable starting point; fuller chronology and detailed claims require source-by-source review.','Introductory source-led Seerah reference; full scholarly authentication of narrative pending.','battle of badr,badr battle,gazwa badr,ghazwa badr,first battle in islam,badr expedition,what happened at badr','Editorial draft based on cited primary references; qualified Seerah specialist review required.','editorial_draft','published','61');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('battle-of-badr-sourced-account-s1','battle-of-badr-sourced-account','Why Badr matters in the Qur’an','scripture','Surah Ali Imran 3:123 explicitly names Badr and recalls Allah’s help when the believers were relatively few. This verse is a primary source for the event’s religious significance. Other nearby verses should be read in context rather than used in isolation as an exhaustive battle narrative.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('battle-of-badr-sourced-account-s2','battle-of-badr-sourced-account','The circumstances and locations','scripture','Surah Al-Anfal 8:42 refers to the near and far sides of a valley and to a caravan being positioned below the groups. The verse addresses the circumstances of their encounter. Quranically does not infer an exact map or invented tactical details from this passage.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('battle-of-badr-sourced-account-s3','battle-of-badr-sourced-account','The expedition in Hadith','transmission','In Sahih al-Bukhari 3951, Ka‘b ibn Malik explains that the Prophet set out with the caravan of Quraysh in view, and the encounter with the opposing force happened without a previous appointment. The Hadith also discusses why those absent from Badr were not blamed. This is a particular transmitted account, not a complete list of participants or events.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('battle-of-badr-sourced-account-s4','battle-of-badr-sourced-account','Boundaries of this introduction','methodology','Specific troop totals, casualty figures, tactical maneuvers and dramatic anecdotes require reference-by-reference verification. This introductory source dossier avoids unsourced embellishment. A qualified Seerah historian should review any detailed chronology or explanation before it is described as fully authenticated.','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('battle-of-badr-sourced-account-r1','battle-of-badr-sourced-account','quran','The Qur’an — Ali Imran','3:123','https://quran.com/3/123','Direct reference to Badr','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('battle-of-badr-sourced-account-r2','battle-of-badr-sourced-account','quran','The Qur’an — Al-Anfal','8:42','https://quran.com/8/42','Encounter and caravan positions','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('battle-of-badr-sourced-account-r3','battle-of-badr-sourced-account','hadith','Sahih al-Bukhari — Military Expeditions','3951','https://sunnah.com/bukhari:3951','Ka‘b ibn Malik’s report on the expedition','pending','3');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('prophetic-guidance-neighbours','prophetic-guidance-neighbours','How the Prophet ﷺ Taught Kindness to Neighbours','حقوق الجار في السنة النبوية','A source-led guide to the rights of neighbours','seerah','historical','The Prophet ﷺ repeatedly emphasised good treatment of neighbours. HadeethEnc record 4965 documents a report about Jibril’s repeated advice concerning neighbours, linked to Sahih al-Bukhari 6014. Qur’an 4:36 also includes kindness to near and distant neighbours. This dossier distinguishes transmitted teachings from editorial practical applications.','Introductory source-led Seerah reference; full scholarly authentication of narrative pending.','neighbour,neighbor,neighbours,neighbors,neighbor rights,neighbour rights,how did prophet treat neighbours,treat his neighbours,kindness to neighbours,prophetic neighbours','Editorial draft based on cited primary references; qualified Seerah specialist review required.','editorial_draft','published','62');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('prophetic-guidance-neighbours-s1','prophetic-guidance-neighbours','The Qur’anic foundation','scripture','Surah An-Nisa 4:36 places kindness to parents, relatives, orphans and other people alongside kindness to near and distant neighbours. The verse is a primary source for the obligation to treat those nearby well; broader jurisprudential details require qualified interpretation.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('prophetic-guidance-neighbours-s2','prophetic-guidance-neighbours','An authenticated transmitted teaching','transmission','A report in Sahih al-Bukhari 6014 explains how frequently Jibril urged the Prophet ﷺ to take care of neighbours, such that the Prophet thought inheritance rights might be assigned. HadeethEnc record 4965 gives a publisher-attributed English translation, grading and explanatory notes. The specific transmission and attribution can be inspected at their original sources.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('prophetic-guidance-neighbours-s3','prophetic-guidance-neighbours','Everyday application','practice','Avoiding harm, showing courtesy, respecting privacy, helping someone in difficulty and treating neighbours fairly are consistent with the sources cited here. These examples are editorial applications of the teaching, not additional sayings quoted from the Prophet ﷺ. The precise limits of neighbourly rights and responsibilities may involve legal and scholarly interpretation.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('prophetic-guidance-neighbours-s4','prophetic-guidance-neighbours','Source and interpretation limits','methodology','The Qur’anic verse and transmitted Hadith provide a reliable foundation, but individual circumstances and obligations can differ. This introductory dossier does not issue a fatwa, rank every report on neighbour rights, or claim that its practical examples are verbatim Prophetic instructions. A qualified scholarly review remains pending.','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('prophetic-guidance-neighbours-r1','prophetic-guidance-neighbours','quran','The Qur’an — An-Nisa','4:36','https://quran.com/4/36','Kindness to near and distant neighbours','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('prophetic-guidance-neighbours-r2','prophetic-guidance-neighbours','hadith','Sahih al-Bukhari — Good Manners','6014','https://sunnah.com/bukhari:6014','Jibril’s repeated advice about neighbours','pending','2');
